void runPing(const std::string& host) {
    // Prevent command injection by passing arguments directly (no shell).
    // Allow-list / validate the host if only IPs/hostnames are expected.
    std::vector<std::string> args = {"ping", "-c", "4", host};
    std::vector<char*> c_args;
    for (auto& a : args) c_args.push_back(&a[0]);
    c_args.push_back(nullptr);
    pid_t pid = fork();
    if (pid == 0) {
        execvp("ping", c_args.data());
        _exit(127);
    } else if (pid > 0) {
        int status;
        waitpid(pid, &status, 0);
    }
}

