void runPing(const std::string& host) {
    // Use execve-style invocation with no shell, or strictly validate host as IPv4/IPv6/hostname
    if (!isValidHost(host)) {
        std::cerr << "Invalid host\n";
        return;
    }
    std::vector<std::string> args = {"ping", "-c", "4", host};
    // Example with fork/execvp, not system()
    pid_t pid = fork();
    if (pid == 0) {
        std::vector<char*> cargs;
        for (auto& a : args) cargs.push_back(const_cast<char*>(a.c_str()));
        cargs.push_back(nullptr);
        execvp(cargs[0], cargs.data());
        _exit(127);
    } else if (pid > 0) {
        int status;
        waitpid(pid, &status, 0);
    }
}

